from work import *
id='local049';base=json.loads((ROOT/'cases'/id/'final.json').read_text())['sql'];base=base[:base.rfind('SELECT industry,total/3.0')]
query(id,"SELECT substr(d.date_joined,1,4) year,count(*) raw_count,count(distinct d.company_id) distinct_companies FROM companies_dates d JOIN companies_industries i USING(company_id) WHERE i.industry='Fintech' AND d.date_joined>='2019-01-01' AND d.date_joined<'2022-01-01' GROUP BY 1",'post-fintech-raw.json')
query(id,"SELECT d.company_id,d.date_joined,count(*) joined_copies FROM companies_dates d JOIN companies_industries i USING(company_id) WHERE i.industry='Fintech' AND d.date_joined>='2019-01-01' AND d.date_joined<'2022-01-01' GROUP BY 1,2 HAVING count(*)>1",'post-fintech-duplicates.json')
query(id,"SELECT (SELECT count(*) FROM companies_dates) date_rows,(SELECT count(*) FROM (SELECT DISTINCT * FROM companies_dates)) distinct_date_rows,(SELECT count(*) FROM companies_industries) industry_rows,(SELECT count(*) FROM (SELECT DISTINCT * FROM companies_industries)) distinct_industry_rows",'post-complete-row-duplicates.json')
query(id,base.replace('SELECT DISTINCT company_id,date_joined,year_founded','SELECT company_id,date_joined,year_founded').replace('SELECT DISTINCT company_id,industry','SELECT company_id,industry').replace('count(distinct company_id) total','count(*) total')+'SELECT industry,total,round(total/3.0,2) answer FROM totals ORDER BY total DESC LIMIT 3','post-raw-final.json')
query(id,base+'SELECT avg(n) changing_year_top FROM (SELECT year,max(n) n FROM (SELECT year,industry,count(distinct company_id) n FROM new_companies GROUP BY 1,2) GROUP BY year)','post-yearly-top.json')
query(id,"SELECT count(*) n,count(distinct d.company_id) ids FROM companies_dates d JOIN companies_industries i USING(company_id) WHERE industry='Fintech' AND year_founded BETWEEN 2019 AND 2021",'post-founded-raw.json')
